import json,re
from pathlib import Path
w=Path(__file__).parent
ledger=json.loads((w/'input/source-ledger.json').read_text())
report=json.loads((w/'input/report-ledger.json').read_text())
reg=json.loads((w/'claims.json').read_text())
# All inspected passages were read in full before verdict construction.
inspected=[{'path':p,'anchor':a} for p,entries in ledger.items() if p.startswith('input/sources/') for a in entries]
def ev(doc,*anchors):
 p='input/sources/'+doc+'.md'
 return [{'path':p,'anchor':a,'quote':ledger[p][a]} for a in anchors]
def proof(name,target,relation='supports'):
 return {'module':'Campaign','theorem':'Campaign.'+name,'relation':relation,'target':target}
def cfg(n,quote,question,evidence,rules,reason,subs,proofs=(),limit=None):
 return dict(n=n,quote=quote,question=question,evidence=evidence,rules=rules,reason=reason,subs=subs,proofs=list(proofs),limit=limit or 'This is a documentary conclusion conditional on faithful transcription of the synthetic packet, not authentication of actual dispatch events.')
L=ev('dispatch-ledger','P02','P03','P04'); P=ev('dispatch-policy','P02','P03','P04','P05','P06'); D=ev('destination-list','P02')
cs=[
cfg(1,'The total amount of the reviewed cohort is 50000 euro cents.','Does the sum of exactly A–D equal 50000 integer euro cents?',L,["L-01 enumerates exactly A–D; sum each L-02 amount once."],['The only cohort amounts are 12000, 18000, 9000 and 11000.','Their sum is 50000.'],['12000 + 18000 + 9000 + 11000 = 50000.'],[proof('total','Campaign.cohortTotal = 50000')]),
cfg(2,'The cohort budget balance is 5000 euro cents.','Does the P-05 comparison-budget-minus-cohort-amount definition yield 5000?',L+ev('dispatch-policy','P06'),['P-05 defines balance as comparison budget less cohort expenditure, with no outside dispatches.'],['L-01 gives budget 55000; independently summing L-02 gives 50000.','Integer subtraction gives 5000; this is not a claim about all-campaign funds.'],['55000 − 50000 = 5000 under the stated balance definition.'],[proof('balance','(55000 : Int) - Campaign.cohortTotal = 5000')]),
cfg(3,'B has compliant approval at cutoff under the temporary exception.','Does B satisfy every conjunct of P-03 at end of day 20?',L+ev('dispatch-policy','P02','P04'),['P-03 requires R2, release 10–14 inclusive, declaration at most two days before release, and approval between release and release+3 inclusive.'],['B is R2 and releases on day 12, within the inclusive window.','Declaration 11 is one day before 12. Approval 15 is three days after 12, and occurred before cutoff 20.','Every exception condition holds.'],['route R2','release day 12 within days 10–14','declaration day 11 one day before release','approval day 15 exactly three days after release','satisfy every exception condition.'],[proof('bException','Campaign.exception Campaign.Dispatch.b')]),
cfg(4,'C has noncompliant approval at cutoff.','Do both and all applicable approval routes fail for C?',L+ev('dispatch-policy','P02','P03','P04'),['Ordinary approval is strictly before release; P-03 permits at most three days after release and exhausts alternate routes.'],['C releases on 12 and its only approval is 16. Thus ordinary approval fails.','Approval is four days after release, exceeding the exception maximum of three.','L-02 states final complete fields and sole approval event; P-03 rules out additional routes. Therefore noncompliance follows within the cohort.'],['approval day 16 is later than release day 12','the ordinary route fails','it is four days after release','the exception also fails.','These are the only approval routes.'],[proof('cNoncompliant','¬ Campaign.compliant Campaign.Dispatch.c')]),
cfg(5,'B is eligible for settlement at cutoff.','Does B satisfy all three necessary and jointly sufficient P-04 conditions?',L+ev('dispatch-policy','P04','P05')+D,['P-04 is a biconditional: compliant approval AND PASS AND membership in DL-7.'],['Independently applying P-03 to B establishes its exception approval.','L-02 records PASS and South; D-01 lists South throughout days 1–20.','All three settlement conditions hold. Delivery acceptance is explicitly not a condition, so its conflict cannot defeat this conclusion.'],['the temporary exception establishes compliant approval','the ledger records checksum PASS','its destination South belongs to DL-7.','These jointly satisfy P-04.'],[proof('bEligible','Campaign.eligible Campaign.Dispatch.b')]),
cfg(6,'Ledger paragraph L-03 restricts the meaning of checksum PASS to package integrity.','Does L-03 actually limit the checksum attestation to package integrity?',ev('dispatch-ledger','P05'),['Interpret the explicit attestation scope, not an implied guarantee of other properties.'],['L-03 states integrity only and explicitly excludes approval timing, acceptance, reliability and settlement.','The report accurately reports the ledger meaning; this does not claim the package is otherwise safe.'],[]),
cfg(7,'The supplied packet cannot establish whether B had zero reliability incidents during days 21–50.','Does the supplied packet determine zero versus any later reliability incidents for B?',ev('packet-register','P02','P03')+ev('dispatch-ledger','P05'),['A through-day-20 packet and checksum integrity do not observe days 21–50. No bridge rule or later observations are supplied.'],['K-01 ends records at day 20; K-02 expressly says later annex not supplied and no observations included.','A later incident count of zero and one are both compatible with that absence of observations; the auxiliary model leaves this omitted count free.','The meta-level evidence limitation is supported; the actual later incident count remains undetermined.'],['the reliability annex is not supplied','there are no observations for that period','this is an evidence limitation, not a finding that an incident occurred.'],[proof('laterAlternatives','Campaign.laterCompatible 0 ∧ Campaign.laterCompatible 1 ∧ (0 : Nat) ≠ 1','auxiliary')], 'No later incident occurrence or nonoccurrence is established. The auxiliary witness formalizes the absence of a supplied constraint; the full packet reading, not the tautological compatibility predicate, justifies that absence.'),
cfg(8,'The supplied packet provides no definition or rating rule for “operationally robust.”','Is an operationally robust definition or rubric present anywhere in the supplied packet?',ev('dispatch-policy','P07')+ev('packet-register','P04'),['A rating needs a supplied operational definition or referenced rubric; none may be invented.'],['P-06 explicitly disclaims the rating definition and incorporation of another standard.','K-03 says no further rubric; full reading of all five sources found no contrary rubric.','The claim concerns packet contents; no objective robustness rating follows.'],[],limit='The absence is bounded to the supplied packet. Standards outside it were not searched, and no external rating is inferred.'),
cfg(9,"The supplied records conflict about B's acceptance at the end of day 12.",'Do two equal-standing records assert and deny the same acceptance event at the same instant?',ev('delivery-records','P02','P03','P04'),['Preserve attribution and compare event, instant, and evidential standing; never conjoin incompatible testimony as world truth.'],['R-01 records B accepted at end of day 12; R-02 denies acceptance at that same instant and event.','R-03 assigns equal evidential standing and supplies no resolution.','The existence of documentary conflict is supported. Actual acceptance remains unresolved; neither source is privileged.'],['R-01 records acceptance','R-02 denies it for the same event and instant','R-03 supplies no resolution.'],limit='No proof of acceptance or rejection is claimed. This supported finding is about conflicting records, not simultaneous truth of incompatible events.'),
cfg(10,"Release on day 15 is outside the temporary exception's release window.",'Is 15 outside the inclusive release interval [10,14] in P-03?',ev('dispatch-policy','P02','P04'),['The exception release window is 10–14 inclusive; ordinary approval is a separate possible route.'],['P-03 gives upper release boundary 14.','Day 15 is greater than 14, hence outside that window. This alone does not imply noncompliance under the ordinary route.'],['the latest permitted release day is 14.'],[proof('outsideWindow','¬ ((10 : Int) ≤ 15 ∧ (15 : Int) ≤ 14)')]),
cfg(11,"The reviewed cohort's eligible settlement amount is 30000 euro cents.",'Which of exactly A–D satisfy P-04, and what is their summed integer amount?',L+P+D,['P-02/P-03 exhaust approval routes; P-04 requires approval, PASS, and listed destination; P-05 sums eligible cohort members only.'],['A has approval 4 < release 5, PASS, North; B has exception approval, PASS, South.','C fails both approval routes; D has ordinary approval and PASS but destination East is explicitly absent from the complete D-01 list.','The nonempty complete cohort is exactly A–D, so eligible members are exactly A and B. Their amounts 12000 and 18000 total 30000.'],['A has prior approval','PASS checksum','listed destination North','B satisfies all three conditions as shown in the cited records','C fails approval timing',"D's destination East is not listed.",'the eligible cohort members are exactly A and B','12000 + 18000 = 30000.'],[proof('eligibleExactly','∀ x : Campaign.Dispatch, Campaign.eligible x ↔ x = Campaign.Dispatch.a ∨ x = Campaign.Dispatch.b'),proof('settlement','Campaign.settlementTotal = 30000')]),
cfg(12,'The supplied four-row ledger does not establish the total amount of all 40 campaign dispatches.','Does four-row cohort evidence determine the sum of the full population of 40 dispatches?',L+ev('packet-register','P04'),['L-01 limits this complete cohort snapshot to four of 40; K-03 denies records and an extrapolation method for the other 36.'],['Known cohort total is 50000, but the other 36 amounts are not supplied.','A completion with each omitted amount zero gives 50000; one euro cent each gives 50036. Neither completion is excluded by the supplied amount constraints.','This auxiliary countermodel pair illustrates nondetermination, not either actual full population total.'],['the snapshot covers four named dispatches','supplies no amounts for the remaining 36.'],[proof('populationAlternatives','Campaign.populationCompletion 0 = 50000 ∧ Campaign.populationCompletion 1 = 50036 ∧ Campaign.populationCompletion 0 ≠ Campaign.populationCompletion 1','auxiliary')], 'The actual full-population total is undetermined; no extrapolation or value for the unprovided 36 records is asserted.')
]
findings=[]
for a in reg['anchors']:
 a['classification']='non_claim' if a['report_anchor'] in ['P01','P02'] else 'claims'
 a['reason']='Title and report framing prescribe review scope and absence of a brief, rather than making an independent source finding.' if a['classification']=='non_claim' else 'Contains a material conclusion and, where present, separately registered supporting premises and inferences.'
reg['claims']=[]
for c in cs:
 n=c['n']; anchor=f'P{n+2:02}'; text=report[anchor]; cid=f'F11-OK-{n:02}'
 assert c['quote'] in text
 citation=re.search(r'Citation[s]?: (.*)$',text).group(1)
 items=[]
 for s in c['subs']:
  assert s in text,(n,s)
  items.append(dict(kind='inference' if any(t in s for t in ['=','fails','satisf','Therefore','only approval','evidence limitation','exactly A and B']) else 'premise',report_anchor=anchor,report_quote=s,assessment='verified',reasoning=' '.join(c['reason']),evidence_refs=list(range(len(c['evidence']))),proof_refs=list(range(len(c['proofs'])))))
 items.append(dict(kind='citation',report_anchor=anchor,report_quote=citation,assessment='verified',reasoning='The named author passages were inspected in context. Their source labels map to the generated ledger anchors below; L-02 includes its separately anchored table. These passages support the stated claim within the disclosed scope.',evidence_refs=list(range(len(c['evidence']))),proof_refs=[]))
 proofs=c['proofs']; auxiliary=bool(proofs) and all(p['relation']=='auxiliary' for p in proofs)
 rationale=('Finite integer model transcribes the recorded amounts, days, finite membership and explicit rules; direct target is scoped to this claim.' if proofs and not auxiliary else 'Auxiliary two-completion witness illustrates the missing constraint; the documentary search establishes which constraints the packet supplies. It is not a direct proof about the unobserved world.' if auxiliary else 'This is a statement about source text, absence of a definition, or attributed disagreement. Direct documentary inspection is the appropriate method; no mathematical proof of external facts is claimed.')
 correspondence=[{'proof_ref':i,'explanation':('L-02 values and P-02/P-03/P-04 rules are transcribed into Campaign declarations; D-01 closes destination membership only during days 1–20. '+ ' '.join(c['reason'])+' The target '+p['target']+' '+('is an auxiliary illustration only; it does not determine any missing value.' if p['relation']=='auxiliary' else 'checks the stated finite calculation or rule evaluation.')+' Faithful transcription and the packet domain are assumed; source authenticity is outside the model.')} for i,p in enumerate(proofs)]
 base=dict(claim_id=cid,report_quote=c['quote'],report_anchor=anchor,question=c['question'],evidence=c['evidence'],rules=c['rules'],assumptions=['The supplied synthetic packet is read literally in its declared scope; source authenticity is not established.'],reasoning=[f'{i+1}. {x}' for i,x in enumerate(c['reason'])],semantic_state='supported',argument_status='sufficient',formal_status='auxiliary' if auxiliary else 'proved' if proofs else 'not_attempted',proofs=proofs,limits=[c['limit']],recommendation='Retain the finding with its stated scope and evidence limitations.',criteria=dict(origin='inferred',operational_question=c['question'],decision_criteria=c['rules'],scope='A–D at cutoff day 20 unless explicitly concerning later days 21–50, acceptance at end of day 12, or the full population of 40.',missing_definitions=['No operational robustness definition or rating rule is supplied.'] if n==8 else [],alternatives=['Actual acceptance and actual later incidents remain unresolved where mentioned; attributed evidence is not world truth.'] if n in (7,9) else []),argument_audit=dict(outcome='sufficient',report_items=items,independent_reasoning=c['reason'],evidence_refs=list(range(len(c['evidence']))),proof_refs=list(range(len(proofs))),claim_dependencies=[]),formalization=dict(rationale=rationale,correspondence=correspondence),support_search=dict(scope='Read every passage of all five supplied sources, checked author citations in context and sought counterevidence; no report text used as independent evidence.',queries=[],inspected=inspected,limitations=['The search is confined to the supplied packet; no withheld annex, other dispatch records, external rating rules or external source authentication are available.'],conclusion=' '.join(c['reason'])))
 findings.append(base)
 reg['claims'].append(dict(claim_id=cid,report_anchor=anchor,report_quote=c['quote'],disposition='audited'))
 for i,s in enumerate(c['subs'],1):
  sub=json.loads(json.dumps(base)); sid=f'{cid}-A{i:02}'
  sub.update(claim_id=sid,report_quote=s,question=f'Does the supplied packet support this explicit premise or inference of {cid}: {s}',formal_status='not_attempted',proofs=[])
  sub['criteria']['operational_question']=sub['question']
  sub['formalization']={'rationale':'This separately registered argument component is checked directly against the source evidence and contextual reasoning. The parent conclusion carries any larger formal calculation; no separate direct proof is claimed for this fragment.','correspondence':[]}
  sub['argument_audit']['proof_refs']=[]
  for it in sub['argument_audit']['report_items']:it['proof_refs']=[]
  sub['limits'].append(f'This fragment is read in its exact parent context {cid}; it is not generalized beyond that dispatch, period or population.')
  findings.append(sub);reg['claims'].append(dict(claim_id=sid,report_anchor=anchor,report_quote=s,disposition='audited'))
(w/'claims.json').write_text(json.dumps(reg,ensure_ascii=False,indent=2)+'\n')
(w/'findings.json').write_text(json.dumps(findings,ensure_ascii=False,indent=2)+'\n')
print(len(findings),'registered and audited claims')
